func (this *Coinbase) HandleTickers(client any, message map[string]any) {
	//
	//    {
	//        "channel": "ticker",
	//        "client_id": "",
	//        "timestamp": "2023-02-09T20:30:37.167359596Z",
	//        "sequence_num": 0,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "tickers": [
	//                    {
	//                        "type": "ticker",
	//                        "product_id": "BTC-USD",
	//                        "price": "21932.98",
	//                        "volume_24_h": "16038.28770938",
	//                        "low_24_h": "21835.29",
	//                        "high_24_h": "23011.18",
	//                        "low_52_w": "15460",
	//                        "high_52_w": "48240",
	//                        "price_percent_chg_24_h": "-4.15775596190603"
	// new as of 2024-04-12
	//                        "best_bid":"21835.29",
	//                        "best_bid_quantity": "0.02000000",
	//                        "best_ask":"23011.18",
	//                        "best_ask_quantity": "0.01500000"
	//                    }
	//                ]
	//            }
	//        ]
	//    }
	//
	//    {
	//        "channel": "ticker_batch",
	//        "client_id": "",
	//        "timestamp": "2023-03-01T12:15:18.382173051Z",
	//        "sequence_num": 0,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "tickers": [
	//                    {
	//                        "type": "ticker",
	//                        "product_id": "DOGE-USD",
	//                        "price": "0.08212",
	//                        "volume_24_h": "242556423.3",
	//                        "low_24_h": "0.07989",
	//                        "high_24_h": "0.08308",
	//                        "low_52_w": "0.04908",
	//                        "high_52_w": "0.1801",
	//                        "price_percent_chg_24_h": "0.50177456859626"
	// new as of 2024-04-12
	//                        "best_bid":"0.07989",
	//                        "best_bid_quantity": "500.0",
	//                        "best_ask":"0.08308",
	//                        "best_ask_quantity": "300.0"
	//                    }
	//                ]
	//            }
	//        ]
	//    }
	//
	// note! seems coinbase might also send empty data like:
	//
	//    {
	//        "channel": "ticker_batch",
	//        "client_id": "",
	//        "timestamp": "2024-05-24T18:22:24.546809523Z",
	//        "sequence_num": 1,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "tickers": [
	//                    {
	//                        "type": "ticker",
	//                        "product_id": "",
	//                        "price": "",
	//                        "volume_24_h": "",
	//                        "low_24_h": "",
	//                        "high_24_h": "",
	//                        "low_52_w": "",
	//                        "high_52_w": "",
	//                        "price_percent_chg_24_h": ""
	//                    }
	//                ]
	//            }
	//        ]
	//    }
	//
	//
	var channel *string = this.SafeString(message, "channel")
	var events []any = ccxt.SafeListTyped(message, "events")
	var datetime *string = this.SafeString(message, "timestamp")
	var timestamp *int64 = this.Parse8601(datetime)
	var newTickers []any = []any{}
	for i := 0; i < len(events); i++ {
		var tickersObj map[string]any = ccxt.MapTyped(func() any {
			if i >= 0 && i < len(events) {
				return ccxt.DerefScalar(events[i])
			}
			return nil
		}())
		var tickers []any = ccxt.SafeListTyped(tickersObj, "tickers")
		for j := 0; j < len(tickers); j++ {
			var ticker any = func() any {
				if j >= 0 && j < len(tickers) {
					return ccxt.DerefScalar(tickers[j])
				}
				return nil
			}()
			var wsMarketId *string = this.SafeString(ticker, "product_id")
			if wsMarketId == nil {
				continue
			}
			var result map[string]any = ccxt.MapTyped(this.ParseWsTicker(ticker))
			result["timestamp"] = timestamp
			result["datetime"] = datetime
			var symbol *string = ccxt.SafeStringPtr(result["symbol"])
			if symbol != nil {
				ccxt.AddElementToObject(this.Tickers, symbol, result)
			}
			newTickers = append(newTickers, result)
			var messageHash any = ccxt.Add(ccxt.Add(channel, "::"), symbol)
			client.(ccxt.ClientInterface).Resolve(result, messageHash)
			this.TryResolveUsdc(client, messageHash, result)
		}
	}
}
func (this *Coinbase) ParseWsTicker(ticker any, optionalArgs ...any) any {
	//
	//     {
	//         "type": "ticker",
	//         "product_id": "DOGE-USD",
	//         "price": "0.08212",
	//         "volume_24_h": "242556423.3",
	//         "low_24_h": "0.07989",
	//         "high_24_h": "0.08308",
	//         "low_52_w": "0.04908",
	//         "high_52_w": "0.1801",
	//         "price_percent_chg_24_h": "0.50177456859626"
	// new as of 2024-04-12
	//         "best_bid":"0.07989",
	//         "best_bid_quantity": "500.0",
	//         "best_ask":"0.08308",
	//         "best_ask_quantity": "300.0"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "product_id")
	var timestamp any = nil
	var last *float64 = this.SafeNumber(ticker, "price")
	return this.SafeTicker(map[string]any{
		"info":          ticker,
		"symbol":        this.SafeSymbol(marketId, market, "-"),
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high_24_h"),
		"low":           this.SafeString(ticker, "low_24_h"),
		"bid":           this.SafeString(ticker, "best_bid"),
		"bidVolume":     this.SafeString(ticker, "best_bid_quantity"),
		"ask":           this.SafeString(ticker, "best_ask"),
		"askVolume":     this.SafeString(ticker, "best_ask_quantity"),
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString(ticker, "price_percent_chg_24_h"),
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "volume_24_h"),
		"quoteVolume":   nil,
	})
}

