func (this *Coinbase) HandleTrade(client any, message map[string]any) {
	//
	//    {
	//        "channel": "market_trades",
	//        "client_id": "",
	//        "timestamp": "2023-02-09T20:19:35.39625135Z",
	//        "sequence_num": 0,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "trades": [
	//                    {
	//                        "trade_id": "000000000",
	//                        "product_id": "ETH-USD",
	//                        "price": "1260.01",
	//                        "size": "0.3",
	//                        "side": "BUY",
	//                        "time": "2019-08-14T20:42:27.265Z",
	//                    }
	//                ]
	//            }
	//        ]
	//    }
	//
	var events any = this.SafeList(message, "events")
	if ccxt.IsEqual(events, nil) {
		return
	}
	var event map[string]any = ccxt.SafeMapTyped(events, 0)
	var trades []any = ccxt.SafeListTyped(event, "trades")
	var trade map[string]any = ccxt.SafeMapTyped(trades, 0)
	var marketId *string = this.SafeString(trade, "product_id")
	var symbol *string = this.SafeSymbol(marketId)
	var messageHash string = "market_trades::" + *symbol
	var tradesArray any = this.SafeValue(this.Trades, symbol)
	if ccxt.IsEqual(tradesArray, nil) {
		var tradesLimit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		tradesArray = ccxt.NewArrayCacheBySymbolById(tradesLimit)
		ccxt.AddElementToObject(this.Trades, symbol, tradesArray)
	}
	for i := 0; i < ccxt.GetArrayLength(events); i++ {
		var currentEvent map[string]any = ccxt.MapTyped(ccxt.GetValue(events, i))
		var currentTrades any = this.SafeList(currentEvent, "trades")
		if ccxt.IsEqual(currentTrades, nil) {
			continue
		}
		// coinbase sends trades newest-first, append them in reverse so the cache stays sorted by ascending timestamp
		var tradesLength int = ccxt.GetArrayLength(currentTrades)
		for j := 0; j < tradesLength; j++ {
			var item any = ccxt.GetValue(currentTrades, (tradesLength-j)-1)
			tradesArray.(ccxt.Appender).Append(this.ParseTrade(item))
		}
	}
	client.(ccxt.ClientInterface).Resolve(tradesArray, messageHash)
	this.TryResolveUsdc(client, messageHash, tradesArray)
}
func (this *Coinbase) HandleOrder(client any, message map[string]any) {
	//
	//    {
	//        "channel": "user",
	//        "client_id": "",
	//        "timestamp": "2023-02-09T20:33:57.609931463Z",
	//        "sequence_num": 0,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "orders": [
	//                    {
	//                        "order_id": "XXX",
	//                        "client_order_id": "YYY",
	//                        "cumulative_quantity": "0",
	//                        "leaves_quantity": "0.000994",
	//                        "avg_price": "0",
	//                        "total_fees": "0",
	//                        "status": "OPEN",
	//                        "product_id": "BTC-USD",
	//                        "creation_time": "2022-12-07T19:42:18.719312Z",
	//                        "order_side": "BUY",
	//                        "order_type": "Limit"
	//                    },
	//                ]
	//            }
	//        ]
	//    }
	//
	var events any = this.SafeList(message, "events")
	if ccxt.IsEqual(events, nil) {
		return
	}
	var marketIds []any = []any{}
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	for i := 0; i < ccxt.GetArrayLength(events); i++ {
		var event map[string]any = ccxt.MapTyped(ccxt.GetValue(events, i))
		var responseOrders any = this.SafeList(event, "orders")
		if ccxt.IsEqual(responseOrders, nil) {
			continue
		}
		for j := 0; j < ccxt.GetArrayLength(responseOrders); j++ {
			var responseOrder any = ccxt.GetValue(responseOrders, j)
			var parsed map[string]any = ccxt.MapTyped(this.ParseWsOrder(responseOrder))
			var cachedOrders any = this.Orders
			var marketId *string = this.SafeString(responseOrder, "product_id")
			if marketId != nil {
				if !(ccxt.InOp(marketIds, marketId)) {
					marketIds = append(marketIds, marketId)
				}
			}
			cachedOrders.(ccxt.Appender).Append(parsed)
		}
	}
	for i := 0; i < len(marketIds); i++ {
		var marketId *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(marketIds) {
				return ccxt.DerefScalar(marketIds[i])
			}
			return nil
		}())
		var symbol *string = this.SafeSymbol(marketId)
		var messageHash string = "user::" + *symbol
		client.(ccxt.ClientInterface).Resolve(this.Orders, messageHash)
		this.TryResolveUsdc(client, messageHash, this.Orders)
	}
	client.(ccxt.ClientInterface).Resolve(this.Orders, "user")
}
func (this *Coinbase) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	//    {
	//        "order_id": "XXX",
	//        "client_order_id": "YYY",
	//        "cumulative_quantity": "0",
	//        "leaves_quantity": "0.000994",
	//        "avg_price": "0",
	//        "total_fees": "0",
	//        "status": "OPEN",
	//        "product_id": "BTC-USD",
	//        "creation_time": "2022-12-07T19:42:18.719312Z",
	//        "order_side": "BUY",
	//        "order_type": "Limit"
	//    }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "order_id")
	var clientOrderId *string = this.SafeString(order, "client_order_id")
	var marketId *string = this.SafeString(order, "product_id")
	var datetime *string = this.SafeString2(order, "time", "creation_time")
	market = ccxt.MapTyped(this.SafeMarket(marketId, market))
	var stopPrice *string = this.SafeString(order, "stop_price")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"symbol":             this.SafeString(market, "symbol"),
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          this.Parse8601(datetime),
		"datetime":           datetime,
		"lastTradeTimestamp": nil,
		"type":               this.SafeString(order, "order_type"),
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               this.SafeStringLower2(order, "side", "order_side"),
		"price":              this.SafeString(order, "limit_price"),
		"stopPrice":          stopPrice,
		"triggerPrice":       stopPrice,
		"amount":             this.SafeString(order, "cumulative_quantity"),
		"cost":               this.OmitZero(this.SafeString(order, "filled_value")),
		"average":            this.SafeString(order, "avg_price"),
		"filled":             this.SafeString(order, "cumulative_quantity"),
		"remaining":          this.SafeString(order, "leaves_quantity"),
		"status":             this.ParseOrderStatus(this.SafeString(order, "status")),
		"fee": map[string]any{
			"amount":   this.SafeString(order, "total_fees"),
			"currency": this.SafeString(market, "quote"),
		},
		"trades": nil,
	})
}
func (this *Coinbase) HandleOrderBookHelper(orderbook any, updates any) {
	for i := 0; i < ccxt.GetArrayLength(updates); i++ {
		var trade map[string]any = ccxt.MapTyped(ccxt.GetValue(updates, i))
		var sideId *string = this.SafeString(trade, "side")
		var side *string = this.SafeString(ccxt.GetValue(this.Options, "sides"), sideId)
		var price *float64 = this.SafeNumber(trade, "price_level")
		var amount *float64 = this.SafeNumber(trade, "new_quantity")
		var orderbookSide any = this.SafeValue(orderbook, side)
		orderbookSide.(ccxt.IOrderBookSide).Store(price, amount)
	}
}
func (this *Coinbase) HandleOrderBook(client any, message map[string]any) {
	//
	//    {
	//        "channel": "l2_data",
	//        "client_id": "",
	//        "timestamp": "2023-02-09T20:32:50.714964855Z",
	//        "sequence_num": 0,
	//        "events": [
	//            {
	//                "type": "snapshot",
	//                "product_id": "BTC-USD",
	//                "updates": [
	//                    {
	//                        "side": "bid",
	//                        "event_time": "1970-01-01T00:00:00Z",
	//                        "price_level": "21921.74",
	//                        "new_quantity": "0.06317902"
	//                    },
	//                    {
	//                        "side": "bid",
	//                        "event_time": "1970-01-01T00:00:00Z",
	//                        "price_level": "21921.3",
	//                        "new_quantity": "0.02"
	//                    },
	//                ]
	//            }
	//        ]
	//    }
	//
	var events any = this.SafeList(message, "events")
	if ccxt.IsEqual(events, nil) {
		return
	}
	var datetime *string = this.SafeString(message, "timestamp")
	for i := 0; i < ccxt.GetArrayLength(events); i++ {
		var event map[string]any = ccxt.MapTyped(ccxt.GetValue(events, i))
		var updates []any = ccxt.SafeListTypedDefault(event, "updates", []any{})
		var marketId *string = this.SafeString(event, "product_id")
		// sometimes we subscribe to BTC/USDC and coinbase returns BTC/USD, as they are aliases
		var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId))
		var symbol *string = ccxt.SafeStringPtr(market["symbol"])
		var messageHash string = "level2::" + *symbol
		var subscription map[string]any = ccxt.SafeMapTyped(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
		var limit *int64 = this.SafeInteger(subscription, "limit")
		var typeVar *string = this.SafeString(event, "type")
		if typeVar != nil && *typeVar == "snapshot" {
			ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}, limit))
		}
		// unknown bug, can't reproduce, but sometimes orderbook is undefined
		if !(ccxt.InOp(this.Orderbooks, symbol)) && ccxt.IsEqual(ccxt.GetValue(this.Orderbooks, symbol), nil) {
			continue
		}
		var orderbook any = ccxt.GetValue(this.Orderbooks, symbol)
		this.HandleOrderBookHelper(orderbook, updates)
		ccxt.AddElementToObject(orderbook, "timestamp", this.Parse8601(datetime))
		ccxt.AddElementToObject(orderbook, "datetime", datetime)
		ccxt.AddElementToObject(orderbook, "symbol", symbol)
		client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
		this.TryResolveUsdc(client, messageHash, orderbook)
	}
}
func (this *Coinbase) TryResolveUsdc(client any, messageHash any, result any) {
	if ccxt.EndsWith(messageHash, "/USD") || ccxt.EndsWith(messageHash, "-USD") {
		client.(ccxt.ClientInterface).Resolve(result, ccxt.Add(messageHash, "C")) // when subscribing to BTC/USDC and coinbase returns BTC/USD, so resolve USDC too
	}
}
func (this *Coinbase) HandleSubscriptionStatus(client any, message map[string]any) any {
	//
	//     {
	//         "type": "subscriptions",
	//         "channels": [
	//             {
	//                 "name": "level2",
	//                 "product_ids": [ "ETH-BTC" ]
	//             }
	//         ]
	//     }
	//
	//
	//      {
	//        channel: 'subscriptions',
	//        client_id: '',
	//        timestamp: '2025-09-15T17:02:49.90120868Z',
	//        sequence_num: 3,
	//        events: [ { subscriptions: {} } ]
	//      }
	//
	var events []any = ccxt.SafeListTypedDefault(message, "events", []any{})
	var firstEvent map[string]any = ccxt.SafeMapTyped(events, 0)
	var isUnsub bool = (func() bool { _, ok := firstEvent["subscriptions"]; return ok }())
	var subKeys []string = ccxt.ObjectKeys(firstEvent["subscriptions"])
	var subKeysLength int = len(subKeys)
	if isUnsub && (subKeysLength == 0) {
		var unSubObject any = this.SafeDict(this.Options, "unSubscription", map[string]any{})
		var messageHashes []any = ccxt.SafeListTyped(unSubObject, "messageHashes")
		var subMessageHashes []any = ccxt.SafeListTyped(unSubObject, "subMessageHashes")
		for i := 0; i < len(messageHashes); i++ {
			var messageHash any = func() any {
				if i >= 0 && i < len(messageHashes) {
					return ccxt.DerefScalar(messageHashes[i])
				}
				return nil
			}()
			var subHash any = func() any {
				if i >= 0 && i < len(subMessageHashes) {
					return ccxt.DerefScalar(subMessageHashes[i])
				}
				return nil
			}()
			this.CleanUnsubscription(ccxt.AsClient(client), subHash, messageHash)
		}
		this.CleanCache(unSubObject)
	}
	return message
}
func (this *Coinbase) HandleHeartbeats(client any, message map[string]any) any {
	// although the subscription takes a product_ids parameter (i.e. symbol),
	// there is no (clear) way of mapping the message back to the symbol.
	//
	//     {
	//         "channel": "heartbeats",
	//         "client_id": "",
	//         "timestamp": "2023-06-23T20:31:26.122969572Z",
	//         "sequence_num": 0,
	//         "events": [
	//           {
	//               "current_time": "2023-06-23 20:31:56.121961769 +0000 UTC m=+91717.525857105",
	//               "heartbeat_counter": "3049"
	//           }
	//         ]
	//     }
	//
	return message
}
func (this *Coinbase) HandleMessage(client any, message any) {
	var channel *string = this.SafeString(message, "channel")
	var methods map[string]any = map[string]any{
		"subscriptions": this.HandleSubscriptionStatus,
		"ticker":        this.HandleTickers,
		"ticker_batch":  this.HandleTickers,
		"market_trades": this.HandleTrade,
		"user":          this.HandleOrder,
		"l2_data":       this.HandleOrderBook,
		"heartbeats":    this.HandleHeartbeats,
	}
	var typeVar *string = this.SafeString(message, "type")
	if typeVar != nil && *typeVar == "error" {
		var errorMessage *string = this.SafeString(message, "message")
		// ternary (not ||) so the ast-transpiler emits a value-typed conditional, not a boolean
		var errorMessageValue any = func() any {
			if errorMessage != nil {
				return errorMessage
			}
			return "unknown error"
		}()
		panic(ccxt.ExchangeError(errorMessageValue))
	}
	var method any = this.SafeValue(methods, channel)
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message)
	}
}

func NewCoinbase(userConfig map[string]any) *Coinbase {
	p := newCoinbase()
	p.Init(userConfig)
	return p
}

func (this *Coinbase) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

